with open("examples/obj_viewer.rs", "r") as f:
    text = f.read()

import re
text = re.sub(r'let \(mesh_source, source_name\) = match args\.input \{\n\s*Some\(path\) => \{\n\s*let content = match fs::read_to_string\(&path\) \{\n\s*Ok\(c\) => c,\n\s*Err\(e\) => \{\n\s*let mut error_table = Table::new\(\);\n\s*error_table\n\s*\.load_preset\(presets::UTF8_FULL\)\n\s*\.set_header\(vec!\[\n\s*Cell::new\("❌ Error Reading File"\)\n\s*\.add_attribute\(comfy_table::Attribute::Bold\)\n\s*\.fg\(Color::Red\),\n\s*\]\)\n\s*\.add_row\(vec!\[\n\s*Cell::new\(format!\("File \\\'{}\\\': {}", path\.display\(\), e\)\)\n\s*\.fg\(Color::Yellow\),\n\s*\]\);\n\s*eprintln!\("\\n{}", error_table\);\n\s*std::process::exit\(1\);\n\s*\}\n\s*\};\n\s*\(content, path\.display\(\)\.to_string\(\)\)\n\s*\},\n\s*None => \(SPACESHIP_OBJ\.to_string\(\), "Built-in Spaceship"\.to_string\(\)\),\n\s*\};', 'let (mesh_source, source_name) = args.input.map_or_else(|| (SPACESHIP_OBJ.to_string(), "Built-in Spaceship".to_string()), |path| {\n        let content = match fs::read_to_string(&path) {\n            Ok(c) => c,\n            Err(e) => {\n                let mut error_table = Table::new();\n                error_table\n                    .load_preset(presets::UTF8_FULL)\n                    .set_header(vec![\n                        Cell::new("❌ Error Reading File")\n                            .add_attribute(comfy_table::Attribute::Bold)\n                            .fg(Color::Red),\n                    ])\n                    .add_row(vec![\n                        Cell::new(format!("File \'{}\': {}", path.display(), e))\n                            .fg(Color::Yellow),\n                    ]);\n                eprintln!("\\n{}", error_table);\n                std::process::exit(1);\n            }\n        };\n        (content, path.display().to_string())\n    });', text)

with open("examples/obj_viewer.rs", "w") as f:
    f.write(text)
